-- Gaia Family server: the server changelog read by the newspaper (2026-10-26).
--
-- Ours, not upstream. One plain sentence per change players can notice,
-- newest last, in the words a player would use (no file names). The Gaia
-- Times prints the changes of the last FamilyChangelogDays days in its
-- "Server updates" section. Every change committed to the family branch adds
-- its line here (see FAMILY.md, "Newspaper").

FamilyChangelogDays = 7

FamilyChangelog = {
	{ "2026-10-17", "Map discovery: Start Discovering in the Cyclopedia map and find the pink vortexes (Measuring Tibia)." },
	{ "2026-10-17", "Offline training counts the whole time away, up to a year; a bed in your house restores health, mana and soul at login." },
	{ "2026-10-17", "Sword, axe and club fighting always share the highest of the three." },
	{ "2026-10-17", "Shared party experience has no level limit and no distance or activity rule." },
	{ "2026-10-17", "Bosses have no cooldown." },
	{ "2026-10-17", "Fresh corpses can be moved right away." },
	{ "2026-10-17", "The Way of the Monk is playable and every monk item can be found." },
	{ "2026-10-18", "The spell list shows only the spells you have learned." },
	{ "2026-10-18", "Vocation bonuses: extra regeneration and critical chance while fed." },
	{ "2026-10-18", "The Tibiadrome arena is open behind the demon trophies." },
	{ "2026-10-18", "NPCs understand whole words first (no more answers to words hidden inside others)." },
	{ "2026-10-18", "Bosses drop Tibia Coins." },
	{ "2026-10-18", "Creatures drop the loot TibiaWiki lists for them." },
	{ "2026-10-18", "The market always has offers to buy and sell." },
	{ "2026-10-18", "The First Dragon: every dragon chest and sacred site counts." },
	{ "2026-10-19", "Houses for sale are furnished; the furniture goes away when you buy one." },
	{ "2026-10-19", "Prey and Hunting Task rerolls and list choices are free." },
	{ "2026-10-19", "Mounts run faster on their home terrain (say !mounts)." },
	{ "2026-10-19", "Edron City Tasks: Daniel Steelsoul has 13 tasks, several at once, at any level." },
	{ "2026-10-20", "New quests: Sinatuki's fish, the Festive Outfit addons, Waterskin of Mead, The Spirit Will Get You and Pilgrimage of Ashes." },
	{ "2026-10-20", "The quest tracker updates right away." },
	{ "2026-10-20", "Skill bars and the spell list stay right after dying." },
	{ "2026-10-20", "The adventurer's stone works anywhere outside a fight; the battle icon ends when no enemy is near." },
	{ "2026-10-21", "Werebadgers and werefoxes on the Troll Sabotage path come out only at night." },
	{ "2026-10-21", "Map discovery points are never inside houses." },
	{ "2026-10-21", "Troll Sabotage: Chief Grarkharok accepts the lady's name." },
	{ "2026-10-21", "Daily reward days 3 and 5 give an XP boost and 25 Tibia Coins instead of Prey rerolls." },
	{ "2026-10-21", "Venore Daily Tasks (ask Norman) and the Braindeath near Beregar's coffin." },
	{ "2026-10-21", "Walter Jaeger sells the Falconer outfit, its addons and the Antelope for Hunting Task points." },
	{ "2026-10-21", "Hunting Tasks pay 10 times the points and a new task can be chosen at once." },
	{ "2026-10-22", "Great mana potions can be drunk by every vocation from level 80." },
	{ "2026-10-22", "Training weapons from the daily reward can be thrown away." },
	{ "2026-10-23", "Tibiadrome: Lorenzo trades Drome points for rewards; rotations every two weeks; 10 minutes between runs." },
	{ "2026-10-23", "Rotworms no longer drop legion helmets." },
	{ "2026-10-23", "Magic level trains faster on statues and dummies, and statue training is twice as fast." },
	{ "2026-10-25", "Tibiadrome runs go on when you take the stairs to the arena's lower floors." },
	{ "2026-10-25", "The Citizen addons show in the quest log." },
	{ "2026-10-25", "New quest: Top of the City in Yalahar (ask Iriana)." },
	{ "2026-10-25", "Exaltation Forge: more dust, cheaper tiers and a better success rate; more influenced creatures near players." },
	{ "2026-10-25", "The market also sells quest items." },
	{ "2026-10-26", "The Gaia Times prints server updates and the adventurers' chronicle of the last day played." },
	{ "2026-10-26", "The Inquisition bosses, the Ankrahmun pharaohs and The Lord of the Lice drop Tibia Coins too." },
	{ "2026-10-26", "New quest: Cartography 101 (ask Rotem Valos in the Adventurers' Guild about a map)." },
	{ "2026-10-26", "New quest: Dragon Slayer Outfits (ask Big Ben in Ab'Dendriel about the dragon slayer attire); Albino Dragons live in five dragon lairs; the First Dragon quest is open all year." },
	{ "2026-10-26", "The adventurers' chronicle records Goshnar's Megalomania bosstiary levels too." },
	{ "2026-10-27", "New promotions at levels 200, 400, 600, 800 and 1000 (say 'promotion' to King Tibianus and the other promoting NPCs; !promotion shows your bonuses)." },
	{ "2026-10-27", "Raid bosses really come now: Orshabaal, Morgaroth, Ghazbaran and Ferumbras about every 20 hours of play, rarer bosses and the Ruthless Seven about every 8, common ones about every 3; other invasions come in random order." },
	{ "2026-10-27", "22 rare bosses that never appeared now come too, on the same timers: among them Hairman the Huge, The Evil Eye, the Rotworm Queen, Willi Wasp, Xenia, Zarabustor, Morshabaal and The Abomination." },
	{ "2026-10-27", "Morshabaal and The Abomination are made for two players: far less health, softer hits (none above 1,500) and much weaker healing." },
	{ "2026-10-27", "Small bosses (20,000 health or less, like Hairman the Huge or the pharaohs) keep their full health; Feroxa's phases and Zamulosh's clones work again." },
	{ "2026-10-28", "Bosses have their Tibia cooldown again (20 hours for most), but every boss cooldown also ends at midnight: a boss killed at 23:00 can be fought again at 00:00." },
	{ "2026-10-28", "The Lion Sanctum doors open for level 250 or more, so its four bosses can be fought (until the An Ancient Feud mission exists)." },
	{ "2026-10-28", "New quest: Grimvale Quest, The Curse Spreads (ask Daniel Steelsoul in Edron about the curse). The five were-beast leaders can only be fought during its last step or after it." },
	{ "2026-10-28", "New quest: Grimvale Quest, An Ancient Feud (after The Curse Spreads, ask Daniel Steelsoul about the lions). The Lion Sanctum doors now open through this mission instead of at level 250." },
	{ "2026-10-28", "The server now notes when the main backpack window or the Manage Containers choices get lost, to find out why they sometimes reset at login (nothing changes in the game)." },
	{ "2026-10-28", "The Curse Spreads: Milos' parchments are in any bookcase of the central tower library (floor +4 one, floor +3 two); the bookcases now always answer, and Milos and the quest log say where to look." },
	{ "2026-10-28", "New quest: Grimvale Quest, The Curse of the Full Moon (Maeryn is on Grimvale now): nightshade blossoms, silver veins and silvered traps; it opens Feroxa's lair, which could not be entered before." },
	{ "2026-10-28", "The bookcases of the Edron academy library open again; a bookcase only hands over Milos' notes while you are looking for them." },
	{ "2026-10-28", "Milos' notes now lie in the same bookcases as in Tibia (two on the library's third floor, one on the fourth) and the scribbled note in a box in the corner of Puffels' room." },
	{ "2026-10-28", "More were-creatures on the first floor of the Edron Lycanthropes Cave: its five quieter rooms now hold twice as many or more." },
	{ "2026-10-30", "The shadow bite plant in the Edron Earth Elemental Cave (second floor) is there now, as in Tibia." },
	{ "2026-10-30", "The Grimvale dock (pier and boat) is a protection zone, as in Tibia." },
	{ "2026-10-30", "Dawnport: you can stay until level 50 (was 20) to finish its quests, and skills and magic level are no longer capped there." },
	{ "2026-10-30", "A character can now be deleted with the account editor on the server PC (option 5, server stopped)." },
	{ "2026-10-30", "To Outfox a Fox (Budrik's mining helmet) now shows in the Tibia Tales quest log, also for those who already finished it." },
	{ "2026-11-01", "Dawnport has no level limit any more: you can stay as long as you like and leave when you choose your vocation." },
	{ "2026-11-01", "Budrik's minotaur task (Turmoil of War, then The Horned Fox) can be taken at any level, not only up to level 40." },
	{ "2026-11-01", "The Dorm Key works again: say key to Woblin, then reward. Mr Morris answers every Dawnport task at every step, and kill tasks start with the first kill." },
	{ "2026-11-01", "Dawnport: Inigo buys creature products, gives his hints one by one and no longer sends you to Rookgaard when you say leave or sure." },
	{ "2026-11-01", "Dawnport: Oressa heals when you say heal, Coltrayne sells weapons and armor behind his counter again, and the bankers answer more questions." },
	{ "2026-11-01", "The Explorer Society: Angus and Mortimer answer every step and say what is missing (an ice pick is not the dwarven pickaxe). Black Bert's strange powder counts, and Elvith sells a lost poetry book." },
	{ "2026-11-01", "The Explorer Society: the spectral stone step works (the essence was never given), and Lurik in Svargrond now gives his missions, which open the Liberty Bay - Svargrond portal." },
	{ "2026-11-01", "New achievements: Just in Time (ice delivery or Rashid's cheese) and Explorer (spectral dress)." },
	{ "2026-11-01", "The Explorer Society: the three missions of each of the first three ranks can be taken together, in any order; after the third you are promoted." },
	{ "2026-11-01", "New: The Frozen Trench. Lurik in Svargrond sends you to dive from the ship south of Tyrsung (helmet of the deep) and find a lost explorer; the trench is full of quara now. Achievement Sea Scout." },
	{ "2026-11-01", "Prey and Hunting Tasks cost Prey Wildcards again, as in Tibia (5 to choose from the full list, lock a slot or cancel a task, 1 to reroll a bonus); list rerolls stay free and the third slot stays open. Daily reward days 3 and 5 give 2 Prey Wildcards too." },
	{ "2026-11-01", "Rerolling a Prey or Hunting Task list costs gold again (level x 200), but each slot has one free reroll a day, back at midnight, and the list after claiming a Hunting Task is free. Daily reward days 3 and 5 now give 5 Prey Wildcards each." },
	{ "2026-11-01", "Grimvale Quest, The Curse Spreads: the alchemical apparatus is back on the north counter of Sinclair's laboratory, so the nightshade distillate can be brewed." },
	{ "2026-11-01", "Grimvale Quest: the wooden grinder in the academy now stands in the middle of its room, complete with its four wooden arms, as in Tibia." },
	{ "2026-11-01", "Grimvale Quest, The Curse Spreads: the basin in the Last Sanctum now moves the quest on; the Moonshadow ritual (the V of white tiles under Grimvale) is what opens the Mystic Flame into the Last Sanctum, as in Tibia. The basin looks tainted until someone lifts the curse, Maeryn can start the mission, NPCs use the Tibia lines, the symbol of Suon also works next to a totem, and finishing it together with The Curse of the Full Moon gives Over the Moon." },
	{ "2026-11-01", "Grimvale Quest, The Curse of the Full Moon now follows TibiaWiki BR: four tasks (Nightshades, Silver Traps, Were-Creatures, Moonshadow). Were-creature kills count from the first one, without talking to Maeryn. Feroxa needs the 50 kills and the Moonshadow ritual; defeating her completes the mission, and both have to be done again (ask Maeryn) to face her once more." },
	{ "2026-11-01", "The Order of the Cobra is complete: the quest log starts in the Cobra Bastion, its ten brass-shod chests give a daily reward, lamp oil burns the tendrils, the skeleton gives Key 0303, the chess notes can be read, Gaffir's secret room opens and the chess board unlocks Scarlett's metal wall." },
	{ "2026-11-02", "Cobra Bastion: escort the Cart Packed with Gold up the basement tunnel after the Custodian (break the clutter, oil its wheels, smash it at the end for loot); the fire walls work; toss a coin in the treasure room to lift the curse of the Strange Rats; Scarlett now taunts everyone in the Bastion when her fight starts." },
	{ "2026-11-02", "Grave Danger: the quest log shows the graves correctly (visited ones were shown as still to find), Jack Springer takes your report at any time, King Zelos' sealed door opens after his briefing, holy water works on both halves of a grave, the emptied graves count when you reach them, and only those who really fought the Custodian pass his flames." },
	{ "2026-11-02", "Grimvale Quest: the three dark stone totems at the sources of the ley lines (Krailos, Banuta, Vengoth) now stand on the same squares as in Tibia, and the stone tablet with ley lines tells you when you are at a source." },
	{ "2026-11-02", "Triangle Tower Quest: the lever in the rubble by the river (desert side, east of the tower) now opens and closes the tower entrance every time; before, once closed, the entrance stayed shut until the server restarted." },
	{ "2026-11-02", "Adventurers' Guild: two new magic forcefields beside the exit take you back to the last two places where you used your adventurer's stone (right = the last one, left = the one before); look at the sign above each field to see where it leads you." },
	{ "2026-11-02", "The Ape City Quest: in deeper Banuta the four canopic jars now break with any melee weapon or a crowbar, and once all four are broken the teleport takes everyone for 5 minutes. Hairycles, Brewster, Ustan and Dermot now say exactly what the wikis show, Hairycles has more to talk about and sells bananas from mission 6 on (statue kits after mission 9)." },
	{ "2026-11-02", "The Dorm Key (Dawnport): Old Nasty bites much more often now. Once Woblin has asked you for the fish, each cast with a worm in his pond has a 1 in 4 chance to catch it." },
	{ "2026-11-02", "Sanctuary of the Lizard God (Dawnport): after offering the snake eggs on the altar, the portal really takes you to the sanctuary now (it always sent you back). Only one egg is used, and if you already offered one you can walk right in." },
	{ "2026-11-02", "Blood Brothers Quest: the whole quest now works, from Julius' map of Vengoth to the four vampire brothers in the castle, with A Wandering Soul, A Fading Memory, the diary pages and the blood goblet. Two of you with charged blood crystals on two of the castle spots are enough to get in, and anyone can wake Marziel. Armenius laughs at 'alori mort' like in Tibia, and sometimes shows his true face." },
	{ "2026-11-02", "Grimvale: the six silver veins on the third floor underground are now proper parts of the cave walls, each next to floor you can stand on, so a pick works on them (before they looked broken and could not be mined)." },
	{ "2026-11-02", "In Service of Yalahar: the city guards take their reports in any order, the notes of Palimuth and Azerus can be read, the weapon crystal really helps Azerus, three ghost residues fill the charm, Morik and the ghost charm come back if lost, Tamerin understands 'warbeasts', and choosing a side gives Follower of Palimuth, Follower of Azerus or Turncoat. The treasure room has a fourth chest with the Yalahari Footwraps." },
	{ "2026-11-02", "Accounts: the account editing tool on the server PC can now create a new character on an account (no vocation, on Dawnport), next to renaming, changing sex and deleting." },
	{ "2026-11-02", "Spells are free now: every spell the spell teachers sell is learned by itself as soon as you reach its level (you get a message for each one), and at login you get all the ones you already have the level for. Quest spells (monk shrines) and Wheel of Destiny spells are still earned as before." },
	{ "2026-11-02", "Sap Strength (sorcerers) can now be cast from level 175, as in Tibia (it needed level 275 before)." },
	{ "2026-11-02", "Houses have a monthly rent again, as in Tibia: every 30 days the house's rent is taken from your bank (keep it there!). Buying still costs the price once and covers the first month; houses you already own have 30 free days. Without the money you get a warning every day for 7 days, then the house is taken back and its items go to your depot. House prices and rents are now Tibia's (about 1.5 times the old prices). Say !house to see when each of your houses is paid until." },
	{ "2026-11-02", "Grimvale: the island surface is quiet now, no were-creatures, bandits or badgers (only butterflies). Moonlight crystals drop much more often from all were-creatures, at the rates players recorded in Tibia, and Feroxa always gives some." },
	{ "2026-11-03", "Grimvale: the full moon is back, every Saturday. That day six were-creatures roam the island surface, the purple nightshades bloom, the silver veins can be mined, and Feroxa returns once after an hour of play. On other days the island is quiet and the nightshades and veins rest." },
	{ "2026-11-03", "Commands now explain themselves: say !commands (or !help) for the list, then !commands and a name for how to use one, with examples, e.g. !commands deposit or !commands transfer. !commands gold lists every command about gold." },
	{ "2026-11-04", "The Djinn War: after finishing one faction, the Orc King now gives you the lamp for the other one too ('hi', 'lamp', 'Malor'). Before, he only answered 'This cursed djinn king!' and kept the lamp." },
	{ "2026-11-06", "The Rookie Guard, Mission 06: the dead poacher in the wolf den gives you the skinning knife again when you use him (before, nothing happened). If you lose the knife before skinning the war wolf, use the body again for a new one." },
	{ "2026-11-06", "The Rookie Guard Quest: saying hi, mission, yes to Vascalir, Lily and Tom now starts their missions (it repeated the first answer). The wasp poison can be taken from a dead wasp again, Tom gives the boots even if the skin was lost after the run, Paulie only pays the bonus for a real deposit, and dying against Kraknaknork no longer pulls you back into his lair." },
	{ "2026-11-06", "The Rookie Guard Quest can now be started at any level: Vascalir no longer turns away characters above level 5, and he no longer stops you at level 8 to warn about level 9." },
	{ "2026-11-08", "The Rookie Guard, Mission 06: the RUUUUN! after skinning the war wolf really makes you faster now (it froze you in place, like an invisible wall), and Tom takes the skin even if you left the den another way. The mythic fire in Grimvale speeds you up too instead of slowing you down." },
	{ "2026-11-08", "Catching a goldfish with an empty goldfish bowl now gives the secret achievement Silent Pet (before, nothing gave it)." },
	{ "2026-11-08", "Fixes from the Canary team: the Store delivers what it shows (the Badger and Floating mounts, Full Trophy Hunter, Oven, Heart Table, Volcanic Spire, both carpets, Exercise Wraps, 500 charges on the Ultimate Health Keg); !deposit, !withdraw and !transfer refuse negative amounts; Lesser Ethereal Spear and Lesser Front Sweep have their own spell ids; True Asuras give more XP; soul regen in resting areas goes up to your vocation's maximum; small fixes for Wyrdin (The New Frontier), Soul War and primal pods." },
	{ "2026-11-08", "No more AFK logout: standing still no longer disconnects you after 15 minutes, not even on the death screen." },
	{ "2026-11-08", "Area runes (great fireball, avalanche, ...) can now be aimed at the square where your own familiar stands; it does not get hurt." },
	{ "2026-11-08", "Rathleton has citizen ranks: Marvin in the magistrate takes your Oramond votes on the shortcut, dungeon, boss and raid topics and promotes you (commoner 25 votes cast, inhabitant 75, citizen 150, squire 250). Every 14 days the votes decide which shortcut slide works and which creatures fill the magistrate dungeon. The City Access slide at the boat, the slide back, the Glooth Factory and the ships to Edron, Venore, Port Hope and Krailos are for citizens only. Elliott and Jacob now want the 20 sewer repairs before giving a vote." },
	{ "2026-11-08", "The Rookie Guard: Vascalir's garlic necklace and silver amulet now come with all their charges and go into your backpack (they had a single charge and broke at the first hit). Lost them? Ask him for the explanation again (Mission 10) or about the flask (Mission 11). Amulets and necklaces from a few other quests (Against the Spider Cult, To Blind the Enemy and some quest chests) also come with full charges now." },
	{ "2026-11-08", "New Oramond tasks for votes: Terrence at the Rathleton gate pays a vote for every 100 rot elementals and glooth blobs, blood beasts, small minotaurs, rustheap golems and metal gargoyles, or big minotaurs (ask him about killing; the higher hunts need a citizen rank); Drystan Wildweed pays 2 votes for 200 glooth bandits and Elbert 2 votes for every 10 glooth capsules (both for citizens, in the Underground Glooth Factory)." },
	{ "2026-11-08", "Magic wolf trap: other monsters walking over it no longer cause a server error; it still catches only starving wolves." },
	{ "2026-11-08", "More Oramond tasks: Terrence pays votes for sabotaging 10 mootant armor racks with cowcoa and sinking 10 turnip crates; Doubleday pays favours for coloured glooth from his sewer machines and for kill combos (Combinatorics), and exchanges them for votes; Dr Merlay can be visited in his lab (drink Roswitha's pint, slip past the statues as a rot elemental) and cured with Alaistar's potion for a vote." },
	{ "2026-11-08", "Two Glooth Factory missions for citizens of Rathleton: Four Demanding Statues (find who leads the glooth bandits for Elbert: bless, adorn, feed and entertain four statues, defeat a warlock, bring his letter) and The Mutated Glooth Plague (Georgia Rainbird, new in the factory: build a glooth converter and clean eight pools of mutated glooth)." },
	{ "2026-11-08", "The last two Oramond tasks for citizens: The Gloud Ship (help Zeronex build a gloud balloon with Nicholas' spider silk cloth, Yeo's gloo cooked at the cauldrons and gas from his old laboratory; then harvesting, concocting and retrieving tasks; Nicholas and the fisherman Yeo are now in Rathleton) and Tending Gloothworms (three daily jobs for Wesley at the gloothworm farm)." },
	{ "2026-11-09", "Rathleton bosses follow the vote at Marvin: Flora waits at the Minotaur Camp when Bullwark is voted (his lever room now works) or in the New Sewers for the Glooth Fairy, and charges one voting right per fight. The Strange Pipe (Hero of Rathleton) now talks only to Rathleton squires." },
	{ "2026-11-09", "Lisa can now be voted and fought too: Flora waits in the Ancient Sewers and Lisa appears in her lever hall. Flora's boss fights need the Rathleton rank inhabitant." },
	{ "2026-11-09", "Glooth Factory raids: every full hour the raid voted at Marvin comes to the factory's second floor for 45 minutes, on top of the usual monsters - minotaurs with totems and the Moohtant Wallbreaker, mechanical creatures with batteries and the Glooth Bomb, or wild life with unstable tunnels and the Tremor Worm. Stop the bosses before they reach the plant wall!" },
	{ "2026-11-09", "Marvin counts the Rathleton votes every week now (Mondays at 06:00) instead of every two weeks." },
	{ "2026-11-09", "The slime slide in the Rathleton magistrate into the Oramond Dungeon now needs the commoner rank (25 votes cast at Marvin), like in Tibia." },
	{ "2026-11-09", "New quest: The Order of the Lion. Visit Evrard the Miller on Bounac by day, earn the trust of the town with the passphrase YSELDA, meet Kesar the Younger, face Fugue at night and Drume on the battlefield, and become the Hero of Bounac. Augustin and the Bounac merchants now trade only with the Hero." },
	{ "2026-11-09", "The Order of the Lion: Kesar and Drume now say their real lines at the meeting, and the Hero of Bounac can enter the town depot through the house south of it." },
	{ "2026-11-09", "Bounac: the crypt warriors on the ground floor of the town come out only at night, and the Hero of Bounac can open three more doors that were always sealed." },
	{ "2026-11-09", "The Order of the Falcon: the nine Grand Master of Verbal Debate volumes can be found in the Falcon Bastion (Master Debater needs all of them), Grand Master Oberon accepts answers with any punctuation, the mission shows in the quest log on arrival and the Zao boat opens after Grand Canon Dominus." },
	{ "2026-11-09", "Falcon Bastion: Key 0808 lies on the kitchen counter again (it comes back after a while), and a can of grease in the cell with the racks opens the gate next to its rusty mechanism for a short time." },
	{ "2026-11-09", "The New Frontier: mission 5 talks only count the six words after farmine and answer with the real lines, Melfar no longer sets the quest back, a lost arena fight can be tried again at once, and Zurak takes winners back to the reward room." },
	{ "2026-11-10", "The New Frontier: the arena reward backpack also holds a transcendence potion, the vines up to Lazaran need mission 3, and Ongulf, Curos, Ztiss and Zurak answer their lore words." },
	{ "2026-11-10", "Steamships to Farmine cost 50 gold less after The New Frontier mission 2, and NPCs no longer repeat the first player's name or price to everyone after." },
	{ "2026-11-10", "The New Frontier quest log: typos fixed and a clearer last mission text; the extra Zurak standing in the water in the Muggy Plains is gone." },
	{ "2026-11-10", "A Pirate's Tail: Eustacio in Venore now gives his mission, and Pirat raids (spyrats in the water, a ship with catapults, or a land invasion) come to Krailos, Thais, Darashia, Port Hope or Liberty Bay; ask him about the location." },
	{ "2026-11-10", "A Pirate's Tail: Tik'hi Tak'he and Om'Wake Naha now live in Rascacoon; the memory test in the mountain gives trust points, and with 1200 of them Tik'hi opens the way to the pirats' ship and Tentugly." },
	{ "2026-11-10", "A Pirate's Tail: Om'Wake Naha's cheese cellar can be defended now (push the cheese into the trapdoor, reveal the spy rats); it gives 200 trust points once every 20 hours." },
	{ "2026-11-11", "A Pirate's Tail: Eustacio's Spy Rat waits in the pirat mines below Rascacoon; sneak through the pirats' laboratory disguised as a rat (watch the guards, the patrols and the lamps; levitate onto the platforms) for 200 trust points once every 20 hours. The spy rats in Om'Wake Naha's cellar now really go for the cheese." },
	{ "2026-11-11", "A Pirate's Tail: Tentugly's Head now fights as in Tibia: servants, a dive, tentacles on both decks that retreat square by square, then the head again; the first victory gives the cheesy key, and the ship goes on to The Wreckoning." },
	{ "2026-11-11", "A Pirate's Tail: Ratmiral Blackwhiskers is fought in four stages now: break the gate with the rum barrel, chase Mister Catkiller and 1st Mate Ratticus across the ship, then face Ratmiral with the bath tub's water against his fire. Each victory gives 100 trust points, and Tik'hi Tak'he gives the Rascoohan outfit." },
	{ "2026-11-12", "Wild horses (Thais): a sugar oat that fails is eaten but the horse stays now, with a 25% chance to tame it per oat. Wild horses come in groups of up to 3 every 3 hours near the Troll Cave entrance; use the oat from the square next to the horse (trap it with parcels or crates)." },
	{ "2026-11-12", "Newspaper sellers now stand still at each city's depot, next to the post officer or at the depot entrance. City walkers no longer get stuck in lines: they spread over the streets, step aside for each other and walk around whoever stands in the way. Their tips no longer repeat until you have heard all that fit your level." },
	{ "2026-11-12", "Newspaper sellers now stroll a little around their depot spot, never into a door, a locker niche or the stairs, and stay put while you talk to them." },
	{ "2026-11-12", "Cobra Bastion: the chess board now reacts when the last piece or the cheesy figurine is placed (before, nothing happened even with the right moves)." },
	{ "2026-11-15", "The Postman Missions: Kevin now gives the real Post Horn, takes bones one by one or all at once, and no longer restarts a mission when you ask him again. The six post officers give their measurements in any order (Lokur first sends you to Kroox), Noodles can be sniffed in any order, and Grand Postmen now sail 10 gold cheaper." },
	{ "2026-11-15", "Post offices: from Assistant Postman (The Postman Missions) letters cost 5 gold and parcels 10 gold, as Kevin promises." },
	{ "2026-11-15", "Royal mailboxes: the ones in the Venore Draccoon cave and on Rascacoon now open for Archpostmen too (their doors could never be opened). Markwin calls 8 bodyguards as in Tibia: 4 archers, 2 guards and 2 mages." },
	{ "2026-11-15", "The Scatterbrained Sorcerer: Eclesius south of Thais finally hires assistants. Five daily tasks in his house and six missions that take you to Venore, Ab'Dendriel, Kazordoon, Carlin and back." },
	{ "2026-11-15", "The Scatterbrained Sorcerer: Samael now screams from his cage (heard near the cellar, in the Thais sewers and in the Thais prison), and the dating questionnaire can also have tolerance or loneliness as the common answer." },
	{ "2026-11-15", "The Scatterbrained Sorcerer: the third mission now takes you into Eclesius' crack in the space-time continuum, a small room in the void under his house, instead of his laboratory." },
	{ "2026-11-16", "Cobra Bastion: in Gaffir's secret room the almanac now gives the last note as a parchment, and the fire portal takes you back in front of the exit of Gaffir's room instead of onto the carpet." },
	{ "2026-11-16", "Blood Brothers Quest: Armenius' cellar (where he shows his true face) is now the whole room, as in Tibia: its western half with the barrels, two wall torches and a blue forcefield that takes you back out to the tavern." },
	{ "2026-11-16", "The Ice Islands Quest: the Formorgar Mines hoist works again, Nilsor takes his seven ingredients in any order and lost ingredients, a lost frost charm or vial of paint can be replaced; the Norseman addons come right with the shards; Sven, Hjaern, Siflind and Nilsor talk about much more." },
	{ "2026-11-16", "The Ice Islands Quest: gathering Nilsor's ingredients now follows Tibia: one every 5 minutes, the cactus, the purple kiss blossom and the geyser water only by day and the frostbite herb only by night." },
	{ "2026-11-16", "War Against the Hive Quest: Orockle on Gray Beach now gives his missions against the Hive Born (acid, blind, digestion, disable, and from the second stage kill and break) with their achievements; the Hive moves to its next stage after 10 missions in a day, Orockle's pheromone opens the hive gates in the third stage, and the insectoid remains give the Insectoid outfit and addons." },
	{ "2026-11-16", "Hive bosses: Chopper, Fleshslicer, Maw, Mindmasher, Rotspit and Shadowstalker now live in the Hive underground while the Hive is in its third stage (back 2 hours after a kill, with dung balls for the war), and The Hungerer, The Manhunter or The Mean Masher sometimes appear on the bottom floor of the Hive Outpost." },
	{ "2026-11-16", "Hot Cuisine Quest: Jean Pierre is home all year and cooks any dish he has taught you again whenever you bring the ingredients (no more once a year); he tells you which ingredients are missing, teaches the new Zaoan Sauce, gives Culinary Master, and the juice squeezer finally makes coconut milk." },
	{ "2026-11-16", "Pot of Blackjack: a pot now lasts four gulps of 5000 health each, as in Tibia, instead of disappearing at the first one." },
	{ "2026-11-16", "Market: it now also sells the quest items of the newer quests (among them the bottled dragon breath, the raccoon backpack and the Pirate's Tail necklaces, the transcendence potion, the Grimvale lizard trophies and the Postman items), like every other quest item." },
	{ "2026-11-16", "The White Raven Monastery Quest: the dead monk's diary is no longer blank (quest books from bodies and chests keep their text), Dalbrect offers his friends the trip with his real words, Costello no longer restarts the investigation when asked again, and the quest now shows as completed in the quest log." },
	{ "2026-11-16", "Isle of the Kings: the bookcase next to Costello now hides Key 3350, which opens the way up to the monks' floors (with monks living there now). But beware: trespassers must pay Costello a fine (crime or absolution) before Captain Jack or Dalbrect will sail them again." },
	{ "2026-11-17", "The Shattered Isles Quest (Meriana): the three plans in the Nargor tavern and the tortoise's nests can be used again, so Ray's missions, the Model Ship and the Pirate Outfit can be finished; Marina's turtle on Meriana rides to the Laguna Islands; Sebastian only sails trusted people to Nargor; the mushroom room to Talahu works; Ocelus, Ray and Chondur talk as on TibiaWiki, and a lost letter or whisper beer can be replaced." },
	{ "2026-11-17", "Forbidden Islands, as on TibiaWiki: Jack Fate now charges 500 gold for Goroma, Chondur's counterspell needs level 35, and each portal of the island teleport rooms only works after you have reached that island the long way and used its portal back once." },
	{ "2026-11-17", "More things now work as on TibiaWiki: Venore's daily tasks open again 20 hours after you report them and the charlatan cave lasts 5 minutes; the Pilgrimage of Ashes pays its gold only if you start it below level 25; the Ape City levers stay pulled 3 minutes and the snake god statue repairs in 60 seconds; Buddel sails to Tyrsung only after Siflind's mission; Lurik, Buddel and Dankwart in Svargrond talk about much more." },
	{ "2026-11-17", "Rookgaard: Vascalir and Hyacinth now speak exactly as on TibiaWiki, and Magister Puffels no longer teaches anyone (as in Tibia since update 15.22; spells are learned automatically here too)." },
	{ "2026-11-17", "Cults of Tibia Quest, as on TibiaWiki: monks get the Sensing Crown from Gerimor; the Zathroth temple barriers take the green souls first and the blue ones second; the Denominator really asks about your number and opens the door; Tigo, Angelo, Jamesfrancis, Gareth, Iwar and Noozer talk as on the wikis; the Barkless ice death brings you back to the temple; every cult shows in the quest log." },
	{ "2026-11-17", "Cults of Tibia Quest: the Goldhanded Cultist Bride now lives in the museum's lowest floor, Enraged Sand Broods join the Sandking's second stage, and the souls you gather in Carlin's forbidden temple fade if you wait more than 10 minutes before using them at their barrier (a barrier stays open once passed)." },
	{ "2026-11-17", "Meriana Rebels and the Pirate Outfit: a pirate leader now really waits in the Nargor hideout after Raymond Striker's pirate task, and the hideout door stays sealed without his permission; Duncan says the codeword; both pirate addons give Swashbuckler. Liberty Bay now has the pirate raids of Tibia: by the boat, at the plantations, and the raid of the four pirate leaders whose items Ariella asks for." },
	{ "2026-11-19", "Crowbar and tool gear: using one on a player, a monster or an NPC no longer causes an error on the server; it simply does nothing." },
	{ "2026-11-20", "The Thieves Guild Quest, as on TibiaWiki: Theodore Loveless' key opens his door again (lock picks too, with a lot of luck), and the door lets you out; you get the valuable vase and the stolen golden goblet; Oswald, Ahmet, Chantalle, Herbert, Carina and Bertram talk as on the wikis; Nurik only deals with the disguised ambassador; the Dark Cathedral teleport needs all six levers; Amateur Actor and Master Thief; Black Bert trades only with those who finished the quest." },
	{ "2026-11-20", "New quest: Kissing a Pig. The talking pig on the Thais farm wants a kiss from the best kisser in the land; learn about kissing from Caramellia (after Hoggle's garden), Elvith (a perfect poem), Lynda (Venorean ice cream), Zebron (dice), the dwarven ghost in the Grothmok tunnel (his fake beard), Toothless Tim (drunk) and the Queen of the Banshees. Reward: Passionate Kisser and the Firlefanz, and Bertram or Chantalle will trade Theodore Loveless' key for a kiss. Also: Nothing Can Stop Me after 100 machete cuts." },
	{ "2026-11-20", "Dark Cathedral (The Thieves Guild, Mission 8): the six levers now stay pulled for 5 minutes, so two players have time to reach the teleport." },
	{ "2026-11-20", "Vampire Hunter Quest, as on TibiaWiki: Storkus now gives the Razing! achievement with the last rank and tells you how many tokens a rank needs; Castlemania also asks for the blood skull from Vengoth castle; Storkus' bookcases have his seven vampire books; the vampire lords bring their companions, Sir Valorcrest drops one token, and The Pale Count is announced, fights first in the hall under Drefia and then again in his sanctuary below." },
	{ "2026-11-22", "Krailos Quest, part 1: Larek in the ogre village now has his three missions (Hungry New World): a skull orchid for his botanist's container, the ancient map from a sarcophagus in the flooded ruins (take diving gear) and the ancient amulet from a bird nest south of the village. Only after that may you use the depot below his tent. He also talks about Krailos as on TibiaWiki." },
	{ "2026-11-22", "Krailos Quest, part 2: Ghorza the shaman has The Great Hunger (make, paint and shake a gourd rattle at three ritual sites, catch her hyaena, repair the protection runes; reward: onyx pendant, and only then does she sell you her potions and runes) and Quenching the Thirst (catch water elemental souls in her carafe, fill the dried salt sea, clean it with golden quartz powder as Larek explains; reward: shaggy ogre bag). The salt sea stays full until 06:00. The hyaena den and a goblin hideout that were missing on our map are now there." },
	{ "2026-11-22", "Krailos Quest, part 3: Grubokk (Survival of the Strongest: sabotage the goblins' water wheels, poison their wells, flood the mines and get out in time) and the goblins (Revolt of the Goblins: holy bog frogs for the imprisoned goblin, a password, the goblin exile's holy weapon for a new runaway goblin, fix the water wheels), one of the two at a time and both again after 00:00; Vuzrog's meals (again after 00:00; Ogre Chef) and his Thunder Tusk Clan task (200 ogre brutes and savages, kills shared by both players; then Mugruu trades with you); The Call of the Wild when all seven Krailos missions are done. The goblin bone key now opens the goblin gates." },	{ "2026-11-22", "Threatened Dreams Quest, checked against TibiaWiki: the Feyrist barrier can now always be finished (the starlight vial no longer counts on the moon mirror), the panpipes no longer undo An Unlikely Couple, the raven herb grows every night, Ahmet really changes the book, Ikassis gives the fae talisman and the fae talk as on the wikis. New: The Fairy Treasure (Tooth Fairy south of Ab'Dendriel, Tired Tree, Grumpy Stone, a treasure in the south of Thais) and Valindara's Swan Feather Cloak (swan feathers by day near the swans of Feyrist). A watering can on a happy sentient oak gives a blessed acorn." },	{ "2026-11-22", "Sweet Dreams: Candia is now a quest as on TibiaWiki. Ask Maelyrra about the donut, free the forest fury from the Corym Black Market, bake and glaze a gingerbread key in Feyrist and open the donut gate. In Candia: the candy lipstick, the Sugar Plum Fairy's four stolen sweets (Kroazur, The Flaming Orchid, Katex Blood Tongue and the new Gorga on the Medusa Tower), the Chocolate Mines with Candis and Sugar Daddy, the Candy Carnival (Toffee), Dulcineo and the Tooth Fairy's toothbrushes for the Pegasus mount, and the runaway taffy bunny." },	{ "2026-11-22", "Candia, the rest of Sweet Dreams: Sugar Daddy now calls his sweet helpers at 3/4, 1/2 and 1/4 health (kill them within 15 seconds or you are hexed and he heals), a spoon on his body refreshes you, and he drops more chocolate coins. Coco at the Candy Carnival sells furniture and gear for milk or dark chocolate coins. Feed marzipan carrots to the taffy bunny for a treasure tip, dig up sand toys and build sand castles. After the quest four real-life recipes hide around Candia. New Candia folk: Jelly, a floating sugar ball and a stressed sugar cube worker." },	{ "2026-11-23", "Freeing the forest fury from the Corym Black Market now really gives the achievement A Friend in Need." },
	{ "2026-11-23", "The Dream Courts Quest, as on TibiaWiki: one arena champion per day in the right order (the arena, its lever and the teleport no longer disagree), the Nightmare Beast curses a player and a dream catcher from the pole in its room passes the curse on, the Faceless Bane needs all 13 iron floors and three rounds, Andrew Lyze checks every material, gives the bait with the golden axe, rewards 50,000 experience and charges compasses again, and his magic portal leads to a chest room; ectoplasm buckets no longer vanish, the stone door needs the Medusa's Ointment, the old lock comes out with a crowbar, Myzzi, Vanys, Undal and Stricken Soul answer as on the wikis (long story, lost talisman, addons in the right order, Dream Catcher and Dream Warrior achievements)." },
	{ "2026-11-23", "The Dream Courts Quest, more: the dimensional portals of the haunted cellar, temple and tomb now carry you between the restored places for one ectoplasm of the place's colour (cellar green, temple red, tomb blue); the graves of the buried cathedral can hold Key 3200 (search again after 10 minutes), which opens the room with a daily reward chest; the powerful Vibrancy imbuement now needs The Dream Courts, as on TibiaWiki (every other imbuement stays open)." },
	{ "2026-11-23", "Goblin Merchant Quest: Rafzan the goblin in the Venore swamp now has his six tasks, all at once and again 20 hours after each report: advertising signs on cracked stones, a rat perfume (slug slime, swamp gas, a rotworm fart, mouldy cheese), shooting adventurers with a makeshift bow, rat urine in the ratmen's pond, smashing junk trunks and killing marsh stalkers (kills count for both of us). Quest log \"Goblin Merchant\"; Task Manager after 500 tasks." },
	{ "2026-11-23", "The Repenters Quest: Ashari in Hellgate now has his four daily tasks, again 20 hours after each report: water the garden with tears from the cradle (mind the leaf golems), catch wild magic in the right colour order for Larfion the Shaman, catch flames from furious fire elementals with the urn (a dwarven ring helps against the fumes) and burn the sick mushrooms with a fire bug. All four in a day: a bonus, the Repenter achievement, sometimes a Pannier Backpack and five passages through his shortcut." },
	{ "2026-11-23", "Adventures of Galthen, Galthen and the Lost Queen: ask Kesar the Younger about Yselda, follow Galthen's trail through Lesh the Seer, Spectulus and Innkeeper Alphonse (both new in Bounac), prepare the soup in the Forest of Life and free Megasylvan Yselda: say the ritual words and keep her four saplings alive with healing. Kesar makes you a royal advisor (Royal Bounacean Advisor outfit); with her saplings alive you also get his violet tulip for Yselda (Bounacean Chivalry) and John the carpenter gives you the first addon at night, then sells his fragments." },
	{ "2026-11-24", "Treasure Hunt Quest, first part: the very old piece of paper now also drops from Brutus Bloodbeard, Deadeye Devious and Ron the Ripper. Use a fire bug on it and bring the text to Wyrdin in Edron; an hour later he has the old pirate poem waiting in the chest behind his door. It leads to a carved giant tree west of Chor in Tiquanda: dig 17 squares west of it into a small dworc cave, break the fence, give your voodoo doll a number in the pot, roll the dice to that number and find the remains of a pirate with the first part of a map." },
	{ "2026-11-24", "Treasure Hunt Quest, second part: show the map part to Klaus in the Nargor tavern and buy his part for 5,000 gold; his logbook waits in the chest behind him. Ask him about the pirates in it, then find Captain Nathaniel's boat in the Waterfall Quest cave and break into Mac Noodles south of the Dwarven Bridge with a crowbar (the last part is under the trough). Klaus stitches the four parts into a pirate treasure map." },
	{ "2026-11-24", "Treasure Hunt Quest, last part: show the pirate treasure map to Captain Waverider on Treasure Island and he sails you to Treasure Hunt Island. Feed rum to the snake head and reach the bridge between the pirate statues within 25 seconds, cross the ship deck without getting hurt, cross the hall of the sleeping dead pirates on the right boards only, give Polly and Skip a cookie each to learn the captain's age for the Skeleton Guard, and take the bejeweled ship's telescope and 3 gold ingots from the treasure room (with a few gems and gold each day)." },
	{ "2026-11-24", "Machinery of War Quest: from level 50, ask Baxter outside Thais castle about the orc war. Repair the 44 broken walls of the outposts around Ulderek's Rock with his bricklayers' kits (orcs attack each finished outpost), set the orcs' 8 ballistae, 8 catapults and the siege tower wheels on fire with a fire bug, and read their war plans on the chalk board in the orc fortress. Report your achievements to Baxter for experience and the ranks henchman, mercenary, orc butcher and war hero. What one of you starts, the other can finish: both get the credit." },
}
